import * as React from 'react'
import { CircleCheck, Info, Lightbulb, TriangleAlert } from 'lucide-react'

import { cx } from '~/lib/cx'
import styles from './callout.module.scss'

export type CalloutTone = 'info' | 'tip' | 'success' | 'warning'

const TONE = {
  info: { tone: styles.info, icon: Info },
  tip: { tone: styles.tip, icon: Lightbulb },
  success: { tone: styles.success, icon: CircleCheck },
  warning: { tone: styles.warning, icon: TriangleAlert },
} as const

export interface CalloutProps {
  tone?: CalloutTone
  title?: React.ReactNode
  children: React.ReactNode
  className?: string
}

export function Callout({
  tone = 'info',
  title,
  children,
  className,
}: CalloutProps) {
  const config = TONE[tone]
  const Icon = config.icon

  return (
    <div className={cx(styles.root, config.tone, className)}>
      <Icon className={styles.icon} aria-hidden />
      <div className={styles.body}>
        {title ? <p className={styles.title}>{title}</p> : null}
        <div className={styles.content}>{children}</div>
      </div>
    </div>
  )
}

@use 'styles' as vz;

.root {
  --callout-bg: #{vz.color('info', 0.05)};
  --callout-border: #{vz.color('info', 0.25)};
  --callout-icon: #{vz.color('info')};

  display: flex;
  gap: vz.space(3);
  padding: vz.space(4);
  border: 1px solid var(--callout-border);
  border-radius: vz.radius('lg');
  background: var(--callout-bg);
  color: vz.color('foreground');
  font-size: vz.font-size('sm');
}

.info {
  --callout-bg: #{vz.color('info', 0.05)};
  --callout-border: #{vz.color('info', 0.25)};
  --callout-icon: #{vz.color('info')};
}

.tip {
  --callout-bg: #{vz.color('primary', 0.05)};
  --callout-border: #{vz.color('primary', 0.25)};
  --callout-icon: #{vz.color('primary')};
}

.success {
  --callout-bg: #{vz.color('success', 0.05)};
  --callout-border: #{vz.color('success', 0.25)};
  --callout-icon: #{vz.color('success')};
}

.warning {
  --callout-bg: #{vz.color('warning', 0.08)};
  --callout-border: #{vz.color('warning', 0.3)};
  --callout-icon: #{vz.color('warning')};
}

.icon {
  margin-top: 2px;
  color: var(--callout-icon);

  @include vz.icon(4);
}

.body {
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
  min-width: 0;
}

.title {
  margin: 0;
  color: vz.color('foreground');
  font-weight: 500;
  line-height: 1.4;
}

.content {
  color: vz.color('muted-foreground');
  line-height: 1.5;
}
